import{_ as t,o as e,c as i,ae as o}from"./chunks/framework.8rYXDNLJ.js";const m=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),l={name:"guide/installation.md"};function n(s,a,r,h,d,c){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p>Download the latest version from <a href="https://github.com/zeroshotlog/portman/releases" target="_blank" rel="noreferrer">GitHub Releases</a>.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li>Open the downloaded <code>.dmg</code> file</li><li>Drag <code>Portman.app</code> to your Applications folder</li><li>Eject the DMG</li></ol><h2 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First Launch&quot;">​</a></h2><p>Since Portman is distributed without an Apple Developer signature, macOS Gatekeeper will show a warning on first launch.</p><h3 id="method-1-right-click-open" tabindex="-1">Method 1: Right-click Open <a class="header-anchor" href="#method-1-right-click-open" aria-label="Permalink to &quot;Method 1: Right-click Open&quot;">​</a></h3><ol><li>Open Finder and navigate to Applications</li><li>Right-click (or Control-click) on <code>Portman.app</code></li><li>Select <strong>Open</strong> from the context menu</li><li>Click <strong>Open</strong> in the security dialog</li></ol><h3 id="method-2-system-settings" tabindex="-1">Method 2: System Settings <a class="header-anchor" href="#method-2-system-settings" aria-label="Permalink to &quot;Method 2: System Settings&quot;">​</a></h3><ol><li>Try to open Portman normally (it will be blocked)</li><li>Go to <strong>System Settings</strong> &gt; <strong>Privacy &amp; Security</strong></li><li>Scroll down to find the message about Portman</li><li>Click <strong>Open Anyway</strong></li></ol><h2 id="verify-download-optional" tabindex="-1">Verify Download (Optional) <a class="header-anchor" href="#verify-download-optional" aria-label="Permalink to &quot;Verify Download (Optional)&quot;">​</a></h2><p>To verify your download hasn&#39;t been tampered with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shasum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 256</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Portman_X.X.X_aarch64.dmg</span></span></code></pre></div><p>Compare the output with the SHA256 hash listed on the release page.</p><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p>To remove Portman:</p><ol><li>Quit Portman if running</li><li>Delete <code>Portman.app</code> from Applications</li><li>(Optional) Remove data: <code>rm -rf ~/.local/share/portman</code></li></ol>',18)])])}const u=t(l,[["render",n]]);export{m as __pageData,u as default};
